using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApproved95()
    {
        var types = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => !t.Name.EndsWith("Marker"))
            .ToList();

        Assert.True(types.Count > 0, "No checkout/pricing behavior exists; cannot compute a payable total (expected 95.00 for Gold at 100.00).");
    }
}
E
